NUM_COLUMNS = 5

class Policy:
    name = "focused_threat_v1"

    def choose_action(self, engine):
        # Map each column to its most advanced pirate (by position, then hp)
        best_pirate = {c: None for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            cur = best_pirate[p.column]
            if cur is None or p.position > cur.position or (
                p.position == cur.position and p.hp > cur.hp
            ):
                best_pirate[p.column] = p

        # Helper to get cannon damage (0 if none)
        def cannon_damage(col):
            c = engine.cannons.get(col)
            return c.damage if c else 0

        # ---------- 1. Immediate threats (position == 2) ----------
        urgent_cols = []
        for col, p in best_pirate.items():
            if p and p.position == 2:
                dmg = cannon_damage(col)
                if dmg < p.hp:          # cannot kill this round
                    urgent_cols.append((col, p, dmg))

        if urgent_cols:
            # pick the column with the biggest hp‑deficit (hardest to kill)
            col, pirate, cur_dmg = max(
                urgent_cols,
                key=lambda tup: (tup[1].hp - tup[2], tup[1].hp)
            )
            deficit = pirate.hp - cur_dmg

            # Try to move a stronger cannon into this column
            source = None
            best_gain = -1
            for src_col, cannon in engine.cannons.items():
                if src_col == col:
                    continue
                gain = cannon.damage - cur_dmg
                if gain > best_gain:
                    best_gain = gain
                    source = src_col
            if source is not None and best_gain > 0:
                # moving sacrifices the pending spawn, but gives us the needed damage now
                return ("move", source, col)

            # otherwise spawn (which will merge if a cannon already exists)
            return ("spawn", col)

        # ---------- 2. Near‑future threats (position == 1) ----------
        near_cols = []
        for col, p in best_pirate.items():
            if p and p.position == 1:
                dmg = cannon_damage(col)
                if dmg < p.hp:
                    near_cols.append((col, p, dmg))

        if near_cols:
            col, pirate, cur_dmg = max(
                near_cols,
                key=lambda tup: (tup[1].hp - tup[2], tup[1].hp)
            )
            # No moving needed here – a single spawn merge is usually enough
            return ("spawn", col)

        # ---------- 3. Fill empty columns that already have pirates ----------
        empty_with_pirate = [
            col for col, p in best_pirate.items()
            if p and col not in engine.cannons
        ]
        if empty_with_pirate:
            # choose the most threatening pirate (highest position, then hp)
            col = max(
                empty_with_pirate,
                key=lambda c: (best_pirate[c].position, best_pirate[c].hp)
            )
            return ("spawn", col)

        # ---------- 4. Strengthen the weakest existing cannon ----------
        if engine.cannons:
            weakest_col = min(
                engine.cannons.items(),
                key=lambda kv: kv[1].damage
            )[0]
            return ("spawn", weakest_col)

        # ---------- 5. No cannons at all – place at the most threatening column ----------
        # (should never happen because case 3 covers it, but keep for safety)
        most_threat = max(
            range(NUM_COLUMNS),
            key=lambda c: (
                best_pirate[c].position if best_pirate[c] else -1,
                best_pirate[c].hp if best_pirate[c] else -1,
            )
        )
        return ("spawn", most_threat)
