The new policy first guarantees survival by eliminating any pirate that is already at the last safe tile (position 2). It does this by adding damage to that column – either by spawning a cannon there (which merges if a cannon already exists) or, when a single +1 merge would not be enough, by moving the weakest spare cannon onto the threatened column. After all immediate threats are handled the policy looks one turn ahead (pirates at position 1) and upgrades those columns similarly. If no urgent upgrades are needed it simply fills empty columns, preferring those that already contain pirates, and otherwise balances damage by spawning on the weakest cannon column.

```python
NUM_COLUMNS = 5


class Policy:
    name = "threat_aware_v1"

    def choose_action(self, engine):
        # ----- helper data structures ---------------------------------------
        # map column -> (lead_position, lead_hp) for the most advanced pirate
        lead_info = {c: (-1, 0) for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            pos, hp = lead_info[p.column][0], lead_info[p.column][1]
            if p.position > pos:
                lead_info[p.column] = (p.position, p.hp)

        # current cannon damage per column (0 if none)
        cannon_damage = {c: 0 for c in range(NUM_COLUMNS)}
        for c, can in engine.cannons.items():
            cannon_damage[c] = can.damage

        # columns that have no cannon
        empty_cols = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]

        # ----- 1. Immediate loss avoidance (pirates at position 2) ----------
        urgent = []
        for c in range(NUM_COLUMNS):
            pos, hp = lead_info[c]
            if pos == 2 and hp > cannon_damage[c]:
                urgent.append((c, hp - cannon_damage[c]))  # (col, deficit)

        if urgent:
            # pick the column with the largest damage deficit
            col, deficit = max(urgent, key=lambda x: (x[1], -x[0]))
            # if a single +1 merge would finish it, just spawn there
            if deficit <= 1:
                return ("spawn", col)
            # otherwise try to move a spare cannon onto this column
            # a spare cannon is one that sits in an empty column (or a column with no pirate)
            # we pick the weakest such cannon to sacrifice
            candidate_sources = [
                (src, engine.cannons[src].damage)
                for src in engine.cannons
                if src != col and (lead_info[src][0] == -1 or lead_info[src][0] < 2)
            ]
            if candidate_sources:
                src, _ = min(candidate_sources, key=lambda kv: (kv[1], kv[0]))
                return ("move", src, col)
            # fallback: just spawn (adds +1)
            return ("spawn", col)

        # ----- 2. Pre‑emptive upgrades (pirates at position 1) ---------------
        soon = []
        for c in range(NUM_COLUMNS):
            pos, hp = lead_info[c]
            if pos == 1 and hp > cannon_damage[c]:
                soon.append((c, hp - cannon_damage[c]))
        if soon:
            col, deficit = max(soon, key=lambda x: (x[1], -x[0]))
            if deficit <= 1:
                return ("spawn", col)
            # need more than +1: try to move a weak spare cannon
            candidate_sources = [
                (src, engine.cannons[src].damage)
                for src in engine.cannons
                if src != col and (lead_info[src][0] == -1 or lead_info[src][0] < 1)
            ]
            if candidate_sources:
                src, _ = min(candidate_sources, key=lambda kv: (kv[1], kv[0]))
                return ("move", src, col)
            return ("spawn", col)

        # ----- 3. Fill empty columns, preferring those with pirates ----------
        if empty_cols:
            # rank empty columns by number of pirates (more is better)
            def pirate_count(col):
                return sum(1 for p in engine.pirates if p.column == col)
            col = max(empty_cols, key=lambda c: (pirate_count(c), -c))
            return ("spawn", col)

        # ----- 4. No empties: balance damage by strengthening weakest cannon --
        # pick the column with the smallest damage; if tie, lowest column index
        weakest_col = min(engine.cannons.items(),
                          key=lambda kv: (kv[1].damage, kv[0]))[0]
        return ("spawn", weakest_col)
