The new policy looks ahead one step and first eliminates any pirate that is about to win (position 2).  If the current cannon in that column cannot kill the front pirate, we immediately merge (spawn) there to raise its damage.  Otherwise we focus on “undersized” columns – those whose cannon damage is still below the maximum HP of any pirate in the column – and boost the column with the biggest deficit.  When all existing cannons are strong enough we fill empty slots (preferring the column that needs the most damage) and, if the board is full, move the weakest cannon toward the column with the highest unmet damage.  This deterministic, threat‑first ordering fixes the main loss cases that the baseline missed and generally builds stronger defenses faster.

```python
NUM_COLUMNS = 5


class Policy:
    name = "threat_first_v1"

    def choose_action(self, engine):
        # ---------- gather column statistics ----------
        # For each column keep the most advanced pirate (highest position)
        col_info = {
            c: {"max_pos": -1, "front_hp": None, "front_tipo": None}
            for c in range(NUM_COLUMNS)
        }
        for p in engine.pirates:
            info = col_info[p.column]
            if p.position > info["max_pos"]:
                info["max_pos"] = p.position
                info["front_hp"] = p.hp
                info["front_tipo"] = p.tipo

        # Needed damage = highest HP of any pirate in the column
        needed_damage = {}
        for c in range(NUM_COLUMNS):
            needed_damage[c] = max(
                (p.hp for p in engine.pirates if p.column == c), default=0
            )

        # Current cannon damage per column
        cannon_damage = {c: engine.cannons[c].damage for c in engine.cannons}

        # ---------- 1. Immediate loss threat (position 2) ----------
        imminent = [
            c for c, info in col_info.items() if info["max_pos"] == 2
        ]  # pirates that will win next move if not killed
        if imminent:
            # Prefer the column where the front pirate has the largest HP
            imminent.sort(key=lambda c: col_info[c]["front_hp"], reverse=True)
            for c in imminent:
                cur_dmg = cannon_damage.get(c, 0)
                front_hp = col_info[c]["front_hp"]
                # If current damage cannot kill it, merge (spawn) here
                if cur_dmg < front_hp:
                    return ("spawn", c)

            # All imminent pirates are already killable – keep building elsewhere
            empty = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]
            if empty:
                return ("spawn", empty[0])

        # ---------- 2. Undersized cannons ----------
        undersized = [
            c
            for c in engine.cannons
            if cannon_damage[c] < needed_damage[c]
        ]
        if undersized:
            # Choose column with the biggest damage deficit (and then highest needed)
            def deficit(col):
                return needed_damage[col] - cannon_damage[col]

            target = max(
                undersized,
                key=lambda c: (deficit(c), needed_damage[c]),
            )
            return ("spawn", target)

        # ---------- 3. Fill empty columns ----------
        empty = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]
        if empty:
            # Prefer the empty column that currently needs the most damage
            target = max(empty, key=lambda c: needed_damage[c])
            return ("spawn", target)

        # ---------- 4. All columns occupied and sufficient ----------
        # Move the weakest cannon toward the column with the highest unmet need
        weakest_col, weakest_cannon = min(
            engine.cannons.items(), key=lambda kv: kv[1].damage
        )
        # Column that would benefit most from extra damage
        target = max(range(NUM_COLUMNS), key=lambda c: needed_damage[c])
        if target != weakest_col:
            return ("move", weakest_col, target)

        # If even moving would not help, merge the weakest cannon (sacrifice spawn)
        return ("spawn", weakest_col)

    # -----------------------------------------------------------------
    # Helper methods (kept for clarity; not used directly by the engine)
    @staticmethod
    def _threat_by_column(engine):
        threats = {c: -1 for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            if p.position > threats[p.column]:
                threats[p.column] = p.position
        return threats
```

